#!/usr/bin/env node
//
// gen-root-index.js
// =============================================================================
// Writes the landing page's root index: the plugin cards and, when a manager version is known, the Krate Manager card,
// filled into docs/index-template.html.
//
// WHY. The root index was generated by the same inline Python in release.yml ("Generate Root Index") and docs.yml;
// the Krate Manager card has to be rendered on plugin releases, docs pushes and manager releases alike, so the
// generator is one Node tool the three workflows call (Krate Manager Phase 12, spec FR-081, D13; plan §4.8, PD-16).
// The plugin cards stay byte for byte what that Python wrote (tools/feed-contract/fixtures/landing/
// root-index.expected.html is its recorded output, SC-029):
//   - plugins are the paths plugins/*/version.json sorted by code unit as paths, not as directory names
//     (plugins/delta-x/version.json sorts before plugins/delta/version.json, tasks TA-11); a name starting "." is not
//     matched, as glob's "*";
//   - per plugin the first tag of `git tag -l "<dir>/v*" --sort=-v:refname`; no tag, no card (and its version.json is
//     not read); the version is the text after the last "/v"; the card links <dir>/ when plugins/<dir>/docs/index.html
//     is a file;
//   - each card is the six-line string of the Python f-strings, the cards joined with "\n";
//   - the template is read with universal newlines ("\r\n" and "\r" become "\n", as Python's text mode), then
//     {{PLUGIN_CARDS}} and then {{REPO}} are replaced everywhere by split/join (str.replace: no "$" patterns), and the
//     page is written UTF-8.
// The manager card is docs/manager-card-template.html with {{MANAGER_VERSION}} and {{REPO}} filled, newlines
// normalised to LF and its trailing newlines trimmed, prepended to the plugin cards as card + "\n" + cards; with no
// manager version (no --manager-version and no manager/vX.Y.Z tag) the page equals the plugin-only page and the card
// template is not read. The newest manager tag is chosen numerically among manager/v<major>.<minor>.<patch> only.
// REPO is the environment's (the Python's os.environ['REPO']); a missing or empty value is refused before any file is
// read, so no page with github.com/undefined links can be written.
// Every git call and file access goes through one injected `deps` object (main throws a TypeError without it);
// productionDeps, which only the entry point builds, runs git with a fixed argument array and no shell.
//
// Usage:
//   node tools/gen-root-index.js --out <file> [--manager-version <x.y.z>]
//   run from the repository root; REPO=<owner/name> in the environment.
// Exit codes: 0 = written, 1 = refused (one stderr line "gen-root-index: <CODE>: <message>", codes
// E_ROOT_INDEX_REPO, E_ROOT_INDEX_TEMPLATE, E_ROOT_INDEX_VERSION_JSON, E_ROOT_INDEX_VERSION), 2 = usage error.
// =============================================================================
'use strict';

const childProcess = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');

const NAME = 'gen-root-index';
const USAGE = 'usage: node tools/gen-root-index.js --out <file> [--manager-version <x.y.z>]';

const INDEX_TEMPLATE = 'docs/index-template.html';
const CARD_TEMPLATE = 'docs/manager-card-template.html';
const MANAGER_TAG_RE = /^manager\/v(\d+)\.(\d+)\.(\d+)$/u;
// D18: the bounded X.Y.Z of a manager release (as tools/gen-manager-latest.js and tools/lint-manager-version.js).
const VERSION_RE = /^(0|[1-9][0-9]{0,8})\.(0|[1-9][0-9]{0,8})\.(0|[1-9][0-9]{0,8})$/u;
const CARD_INDENT = ' '.repeat(16);
const LINE_INDENT = ' '.repeat(20);

class RootIndexError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'RootIndexError';
    this.code = code;
  }
}

function universalNewlines(text) {
  return text.replace(/\r\n?/gu, '\n');
}

function replaceAll(text, placeholder, value) {
  return text.split(placeholder).join(value);
}

function compareParts(a, b) {
  for (let i = 0; i < a.length; i += 1) {
    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
  }
  return 0;
}

/** The newest manager/v<major>.<minor>.<patch> tag's version, compared numerically; null when there is none. */
function newestManagerVersion(tags) {
  let best = null;
  for (const tag of tags) {
    const m = MANAGER_TAG_RE.exec(tag);
    if (!m) continue;
    const parts = m.slice(1, 4).map((d) => BigInt(d));
    if (best === null || compareParts(parts, best.parts) > 0) best = { parts, version: tag.slice('manager/v'.length) };
  }
  return best === null ? null : best.version;
}

/** The manager card: '' without a version, else the template filled, LF, trailing newlines trimmed. */
function renderManagerCard({ version, template, repo }) {
  if (version === null) return '';
  const filled = replaceAll(replaceAll(template, '{{MANAGER_VERSION}}', version), '{{REPO}}', repo);
  return universalNewlines(filled).replace(/\n+$/u, '');
}

/** The plugin cards of the Python f-strings (release.yml:823-836 at 7c4b6837), joined with "\n". */
function renderPluginCards(plugins) {
  return plugins
    .map((p) => {
      const open = p.hasPage ? `<a href="${p.dir}/" class="plugin-card">` : '<div class="plugin-card">';
      const close = p.hasPage ? '</a>' : '</div>';
      return [
        `${CARD_INDENT}${open}`,
        `${LINE_INDENT}<h2>${p.name}</h2>`,
        `${LINE_INDENT}<p class="description">${p.description}</p>`,
        `${LINE_INDENT}<span class="version">v${p.version}</span>`,
        `${CARD_INDENT}${close}`,
      ].join('\n');
    })
    .join('\n');
}

/** The page: the manager card prepended to the plugin cards in {{PLUGIN_CARDS}}, then {{REPO}} replaced. */
function renderRootIndex({ pluginCards, managerCard, template, repo }) {
  const cards = managerCard === '' ? pluginCards : `${managerCard}\n${pluginCards}`;
  return replaceAll(replaceAll(universalNewlines(template), '{{PLUGIN_CARDS}}', cards), '{{REPO}}', repo);
}

/** The tagged plugins under <root>/plugins in the Python's order: { dir, name, description, version, hasPage }. */
function collectPlugins(deps, root) {
  const rels = deps
    .readDir(path.join(root, 'plugins'))
    .filter((dir) => !dir.startsWith('.') && deps.isFile(path.join(root, 'plugins', dir, 'version.json')))
    .map((dir) => `plugins/${dir}/version.json`)
    .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const plugins = [];
  for (const rel of rels) {
    const dir = rel.split('/')[1];
    const tag = (deps.gitTags(`${dir}/v*`)[0] ?? '').trim();
    if (tag === '') continue;
    let data;
    try {
      data = JSON.parse(deps.readFile(path.join(root, ...rel.split('/'))));
    } catch (err) {
      throw new RootIndexError('E_ROOT_INDEX_VERSION_JSON', `${rel}: ${err.message}`);
    }
    if (data === null || typeof data !== 'object' || Array.isArray(data)) {
      throw new RootIndexError('E_ROOT_INDEX_VERSION_JSON', `${rel}: not a JSON object`);
    }
    for (const field of ['name', 'description']) {
      if (typeof data[field] !== 'string') {
        throw new RootIndexError('E_ROOT_INDEX_VERSION_JSON', `${rel}: "${field}" is not a string`);
      }
    }
    plugins.push({
      dir,
      name: data.name,
      description: data.description,
      version: tag.split('/v').pop(),
      hasPage: deps.isFile(path.join(root, 'plugins', dir, 'docs', 'index.html')),
    });
  }
  return plugins;
}

function parseArgs(argv) {
  const opts = new Map();
  for (let i = 0; i < argv.length; i += 2) {
    const flag = argv[i];
    if (flag !== '--out' && flag !== '--manager-version') return null;
    if (opts.has(flag) || i + 1 >= argv.length) return null;
    opts.set(flag, argv[i + 1]);
  }
  if (!opts.has('--out') || opts.get('--out') === '') return null;
  return { out: opts.get('--out'), managerVersion: opts.has('--manager-version') ? opts.get('--manager-version') : null };
}

function readTemplate(deps, root, rel) {
  try {
    return deps.readFile(path.join(root, ...rel.split('/')));
  } catch (err) {
    throw new RootIndexError('E_ROOT_INDEX_TEMPLATE', `${rel}: ${err.message}`);
  }
}

function main(argv, io, deps) {
  if (deps === null || typeof deps !== 'object') {
    throw new TypeError(
      `${NAME}: main(argv, io, deps): deps is required (gitTags, repo, readFile, readDir, isFile, writeFile, root; ` +
        'only the entry point builds productionDeps())',
    );
  }
  const args = parseArgs(argv);
  if (args === null) {
    io.stderr.write(`${NAME}: E_USAGE: ${JSON.stringify(argv)}\n${USAGE}\n`);
    return 2;
  }
  try {
    const repo = deps.repo();
    if (typeof repo !== 'string' || repo === '') {
      throw new RootIndexError('E_ROOT_INDEX_REPO', 'REPO is not set in the environment');
    }
    if (args.managerVersion !== null && !VERSION_RE.test(args.managerVersion)) {
      throw new RootIndexError(
        'E_ROOT_INDEX_VERSION',
        `--manager-version ${JSON.stringify(args.managerVersion)} is not <major>.<minor>.<patch>`,
      );
    }
    const version = args.managerVersion ?? newestManagerVersion(deps.gitTags('manager/v*'));
    const root = deps.root;
    const template = readTemplate(deps, root, INDEX_TEMPLATE);
    const managerCard =
      version === null ? '' : renderManagerCard({ version, template: readTemplate(deps, root, CARD_TEMPLATE), repo });
    const plugins = collectPlugins(deps, root);
    const html = renderRootIndex({ pluginCards: renderPluginCards(plugins), managerCard, template, repo });
    const out = path.resolve(root, args.out);
    deps.writeFile(out, html);
    const card = version === null ? 'no manager card' : `manager card v${version}`;
    io.stdout.write(`${NAME}: ok, wrote ${args.out} (${plugins.length} plugin cards, ${card})\n`);
    return 0;
  } catch (err) {
    if (!(err instanceof RootIndexError)) throw err;
    io.stderr.write(`${NAME}: ${err.code}: ${err.message}\n`);
    return 1;
  }
}

function productionDeps() {
  return {
    root: process.cwd(),
    gitTags: (pattern) =>
      childProcess
        .execFileSync('git', ['tag', '-l', pattern, '--sort=-v:refname'], { encoding: 'utf8' })
        .split('\n')
        .map((line) => line.trim())
        .filter((line) => line !== ''),
    repo: () => process.env.REPO,
    readFile: (p) => fs.readFileSync(p, 'utf8'),
    readDir: (p) => fs.readdirSync(p),
    isFile: (p) => {
      const st = fs.statSync(p, { throwIfNoEntry: false });
      return st !== undefined && st.isFile();
    },
    writeFile: (p, text) => {
      fs.mkdirSync(path.dirname(p), { recursive: true });
      fs.writeFileSync(p, text, 'utf8');
    },
  };
}

module.exports = {
  newestManagerVersion,
  renderManagerCard,
  renderPluginCards,
  renderRootIndex,
  collectPlugins,
  main,
  productionDeps,
};

if (require.main === module) process.exitCode = main(process.argv.slice(2), process, productionDeps());
